mapper.select:
		SELECT MY_SKILL_CODE
			   , RESUME_NO
			   , MY_SKILL_NAME
		  FROM MY_SKILL 
		 WHERE MY_SKILL_CODE = #{mySkillCode}
     	   AND RESUME_NO = #{resumeNo}

mapper.insert:

    SELECT
        'MYSK'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(MY_SKILL_CODE), LENGTH('MYSK' ) + 1)), 0) + 1, 6, '0')
    FROM MY_SKILL

INSERT INTO MY_SKILL (
	MY_SKILL_CODE
	, RESUME_NO
	, MY_SKILL_NAME
) VALUES (
	#{mySkillCode}
	, #{resumeNo}
	, #{mySkillName}
)

mapper.update:
UPDATE MY_SKILL
   SET RESUME_NO = #{resumeNo}
   	   , MY_SKILL_NAME = #{mySkillName} 
 WHERE MY_SKILL_CODE = #{mySkillCode}
